import type { HelpGuide } from "./guides";
import type { PermissionKey } from "@/lib/permissions/catalog";

type Shortcut = [key: string, label: string, href: string, permission?: PermissionKey];
function guide(id: string, area: string, title: string, description: string, steps: string[], shortcuts: Shortcut[], note?: string): HelpGuide {
  return { id, area, title, description, steps, note, links: shortcuts.map(([key, label, href, permission]) => ({ key, label, href, ...(permission ? { permission } : {}) })) };
}
